pub fn find_python(honor_env: bool) -> Result<String, String> {
    if honor_env {
        if let Ok(p) = std::env::var("PYFUN_PYTHON") {
            if !p.is_empty() {
                return Ok(p);
            }
        }
    }
    for cand in ["python", "python3"] {
        let ok = std::process::Command::new(cand)
