    let a = parse_compile_args("compile", args);
    let ck = load_checked(&a.file, true);
    let em = project::emit_all(&ck, &project::EmitOpts { py311: a.py311, native: a.native });
    let project = ck.mods.len() > 1;
    match (&a.out, project) {
        (None, false) => print!("{}", em.files[0].1),
        (None, true) => {
            for (f, text) in &em.files {
                println!("# ==== {} ====", f);
                print!("{}", text);
                println!();
            }
        }
        (Some(o), false) => {
            if let Err(e) = std::fs::write(o, &em.files[0].1) {
                fail(&format!("error: cannot write {}: {}", o, e));
            }
            eprintln!("wrote {}", o);
        }
        (Some(o), true) => {
            if let Err(e) = std::fs::create_dir_all(o) {
                fail(&format!("error: cannot create {}: {}", o, e));
            }
            for (f, text) in &em.files {
                let p = Path::new(o).join(f);
                if let Err(e) = std::fs::write(&p, text) {
                    fail(&format!("error: cannot write {}: {}", p.display(), e));
                }
            }
            eprintln!("wrote {} files to {}", em.files.len(), o);
        }
    }
}

/// The Python interpreter to use: PYFUN_PYTHON, else `python`, else `python3`.
pub fn find_python(honor_env: bool) -> Result<String, String> {
    if honor_env {
        if let Ok(p) = std::env::var("PYFUN_PYTHON") {
            if !p.is_empty() {
                return Ok(p);
            }
        }
    }
    for cand in ["python", "python3"] {
        let ok = std::process::Command::new(cand)
            .arg("--version")
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .map(|s| s.success())
            .unwrap_or(false);
        if ok {
            return Ok(cand.to_string());
        }
    }
    Err("no Python interpreter found on PATH (tried `python`, `python3`)".to_string())
}

fn cmd_run(args: &[String]) {
    let Some(path) = args.first() else { fail("error: `run` needs a file path") };
    let mut rest: Vec<String> = args[1..].to_vec();
    if rest.first().map(|s| s.as_str()) == Some("--") {
        rest.remove(0);
    }
    let ck = load_checked(path, true);
    let em = project::emit_all(&ck, &project::EmitOpts { py311: false, native: false });
    let python = match find_python(true) {
        Ok(p) => p,
        Err(e) => fail(&format!("error: {}", e)),
    };
    let dir: PathBuf = std::env::temp_dir().join(format!("pyfun_run_{}", std::process::id()));
    let _ = std::fs::create_dir_all(&dir);
    let project = ck.mods.len() > 1;
    let main_file = if project { format!("{}.py", project::py_module_of(&ck.mods.last().unwrap().file)) } else { "_pyfun_main.py".to_string() };
    if project {
        for (f, text) in &em.files {
            let _ = std::fs::write(dir.join(f), text);
        }
    } else {
        let _ = std::fs::write(dir.join(&main_file), &em.files[0].1);
    }
    let script = dir.join(&main_file);
    let status = std::process::Command::new(&python).arg(&script).args(&rest).status();
    let _ = std::fs::remove_dir_all(&dir);
    match status {
        Ok(s) => exit(if s.success() { 0 } else { 1 }),
        Err(e) => fail(&format!("error: `{}` did not finish: {}", python, e)),
    }
}

fn cmd_parse(args: &[String]) {
    let Some(path) = args.first() else { fail("error: `parse` needs a file path") };
    let src = load_source(path);
    match parser::parse_program(&src) {
"}}}

item.aggregated_output:
    match parser::parse_program(&src) {
        Ok(p) => print!("{}", printer::print_program(&p)),
        Err(d) => {
            eprintln!("{}", diag::render(&src, &d));
            exit(1);
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.is_empty() || args[0] == "-h" || args[0] == "--help" {
        eprint!("{}", USAGE);
        exit(0);
    }
    let rest = &args[1..];
    match args[0].as_str() {
        "--version" | "-V" | "version" => println!("pyfun {}", VERSION),
        "check" => cmd_check(rest),
        "compile" => cmd_compile(rest),
        "run" => cmd_run(rest),
        "parse" => cmd_parse(rest),
        "bundle" => bundle::cmd_bundle(rest),
        "build" => bundle::cmd_build(rest),
        "add" => pkg::cmd_add(rest),
        "install" => pkg::cmd_install(rest),
        "remove" => pkg::cmd_remove(rest),
        "repl" => repl::run_repl(),
        "kernel-engine" => kernel::run_kernel(),
        "lsp" => lsp::run_lsp(),
        _ => cmd_compile(&args[..1]),
    }
}
// What the checker remembers for the language server: the type of every
// expression and binding (for hover), every definition and use of a name
// (for go-to-definition, references and rename), and where constructors and
// types are mentioned.

use crate::source::Span;
use crate::types::Ty;
use std::collections::HashMap;

pub const NO_DEF: usize = usize::MAX;

/// Where a hover's documentation comes from.
#[derive(Clone, Debug)]
pub enum Doc {
    None,
    /// a user definition (its `##` comment)
    Def(usize),
    /// a library function, by name
    Builtin(String),
    /// written out
    Text(String),
}

/// Something with a type at a span.
#[derive(Clone, Debug)]
pub struct Item {
    pub span: Span,
    /// None for a binding whose type could not be found
    pub ty: Option<Ty>,
    pub doc: Doc,
}

#[derive(Clone, Debug)]
pub struct Def {
    pub name: String,
    pub span: Span,
    pub doc: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub struct Ide {
    /// hoverable things in the order they were checked
    pub items: Vec<Item>,
    pub defs: Vec<Def>,
    /// a use of a name: (span, definition)
    pub uses: Vec<(Span, usize)>,
    /// definitions by the span that introduces them
    pub def_at: HashMap<(usize, usize), usize>,
    /// constructor mentions in expressions and patterns: (span, name)
    pub ctor_uses: Vec<(Span, String)>,
    /// type names mentioned in types, record literals and record patterns
    pub type_uses: Vec<(Span, String)>,
    /// library names used: (span, name)
    pub builtin_uses: Vec<(Span, String)>,
    /// names that resolve to nothing: (span, name)
    pub unbound_uses: Vec<(Span, String)>,
    /// types the program declares
    pub user_types: std::collections::HashSet<String>,
    /// checking a `let` destructuring pattern
    pub in_let_pattern: bool,
}

impl Ide {
    /// The definition introduced at `span`, made on first sight.
    pub fn def(&mut self, name: &str, span: Span, doc: Option<String>) -> (usize, bool) {
        if let Some(&d) = self.def_at.get(&(span.lo, span.hi)) {
            return (d, false);
        }
        let id = self.defs.len();
        self.defs.push(Def { name: name.to_string(), span, doc });
        self.def_at.insert((span.lo, span.hi), id);
        (id, true)
    }

    pub fn item(&mut self, span: Span, ty: &Ty, doc: Doc) {
        self.items.push(Item { span, ty: Some(ty.clone()), doc });
    }

    /// A binding that failed to check: only its documentation is known.
    pub fn untyped(&mut self, span: Span, doc: Doc) {
        self.items.push(Item { span, ty: None, doc });
    }
}
// rustc-style diagnostics.

use crate::source::{line_col, line_text, Span};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Severity {
    Error,
    Note,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Diag {
    pub severity: Severity,
    pub msg: String,
    pub span: Span,
}

impl Diag {
    pub fn error(msg: impl Into<String>, span: Span) -> Diag {
        Diag { severity: Severity::Error, msg: msg.into(), span }
    }
    pub fn note(msg: impl Into<String>, span: Span) -> Diag {
        Diag { severity: Severity::Note, msg: msg.into(), span }
    }
}

/// Render one diagnostic against its source, without a trailing newline.
pub fn render(src: &str, d: &Diag) -> String {
    let head = match d.severity {
        Severity::Error => "error",
        Severity::Note => "note",
    };
    let (line, col) = line_col(src, d.span.lo);
    let text = line_text(src, line);
    let lnum = line.to_string();
    let pad = " ".repeat(lnum.len());
    // the caret covers the span's bytes on its first line, at least one
    let line_end = col - 1 + (text.len() + 1 - col.min(text.len() + 1));
    let hi_col = {
        let (hl, hc) = line_col(src, d.span.hi);
        if hl == line {
            hc - 1
        } else {
            line_end
        }
    };
    let n = if hi_col > col - 1 { hi_col - (col - 1) } else { 1 };
    format!(
        "{}: {}\n{}--> {}:{}\n{} |\n{} | {}\n{} | {}{}",
        head,
        d.msg,
        pad,
        line,
        col,
        pad,
        lnum,
        text,
        pad,
        " ".repeat(col - 1),
        "^".repeat(n)
    )
}
// Byte spans and line/column lookup.

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Default, PartialOrd, Ord)]
pub struct Span {
    pub lo: usize,
    pub hi: usize,
}

impl Span {
    pub fn new(lo: usize, hi: usize) -> Span {
        Span { lo, hi }
    }
    pub fn to(self, other: Span) -> Span {
        Span { lo: self.lo.min(other.lo), hi: self.hi.max(other.hi) }
    }
}

/// 1-based line and byte column of an offset.
pub fn line_col(src: &str, off: usize) -> (usize, usize) {
    let bytes = src.as_bytes();
    let off = off.min(bytes.len());
    let mut line = 1;
    let mut ls = 0;
    for (i, &b) in bytes[..off].iter().enumerate() {
        if b == b'\n' {
            line += 1;
            ls = i + 1;
        }
    }
    (line, off - ls + 1)
}

/// The text of a 1-based line (without its newline).
pub fn line_text(src: &str, line: usize) -> &str {
    src.split('\n').nth(line - 1).unwrap_or("")
}
// `--native`: annotations for mypyc. Module-level values, function
// signatures and class fields carry Python types where they say something
// mypyc can use; sum types get a union alias; ordering methods are written
// out instead of `functools.total_ordering`.

use crate::infer::*;
use crate::lower::Lowerer;
use crate::types::*;

impl<'a> Lowerer<'a> {
    /// The annotation for a value of type `t`, if it has one: functions,
    /// lazy and asynchronous values and foreign types have none. An unknown
    /// part reads as `Any` when `vars` (module-level values), and leaves
    /// the annotation out otherwise (signatures).
    pub fn native_ann(&mut self, t: &Ty, vars: bool) -> Option<String> {
        let t = self.ck.st.resolve(t);
        match &t {
            Ty::Var(_) | Ty::Gen(_) => {
                if vars {
                    self.needs.any = true;
                    Some("Any".into())
                } else {
                    None
                }
            }
            Ty::Num(k, _) => Some(if self.ck.st.kind(*k) == Kind::Float { "float".into() } else { "int".into() }),
            Ty::Fun(..) => None,
            Ty::Tuple(ts) => {
                let mut parts = Vec::new();
                for x in ts {
                    parts.push(self.native_ann(x, vars)?);
                }
                Some(format!("tuple[{}]", parts.join(", ")))
            }
            Ty::Con(n, args) => match (n.as_str(), args.len()) {
                ("bool", 0) => Some("bool".into()),
                ("string", 0) => Some("str".into()),
                ("unit", 0) => Some("None".into()),
                ("List", 1) => Some(format!("list[{}]", self.native_ann(&args[0], vars)?)),
                ("Set", 1) => Some(format!("set[{}]", self.native_ann(&args[0], vars)?)),
                ("Map", 2) => {
                    let k = self.native_ann(&args[0], vars)?;
                    let v = self.native_ann(&args[1], vars)?;
                    Some(format!("dict[{}, {}]", k, v))
                }
                // whether the classes exist is known once the module is lowered
                ("Option", 1) => Some(OPTION_MARK.to_string()),
                ("Result", 2) => Some(RESULT_MARK.to_string()),
                _ => self.user_type_ann(n),
            },
        }
    }

    /// A type this module declares, by the name its class or alias goes by.
    fn user_type_ann(&self, n: &str) -> Option<String> {
        let info = self.ck.types.get(n)?;
        if info.module.is_some() || !self.has_code {
            return None;
        }
        match &info.def {
            TypeDef::Adt(ctors) if !ctors.iter().any(|c| c == n) => Some(n.to_string()),
            TypeDef::Record(_) => Some(n.to_string()),
            _ => None,
        }
    }

    /// A class field's annotation: the plain types as they are, the
    /// containers bare, a type declared here as a forward reference.
    pub fn native_field_ann(&mut self, t: &Ty) -> String {
        let s = match t {
            Ty::Num(Kind::Int, _) => "int".to_string(),
            Ty::Num(Kind::Float, _) => "float".to_string(),
            Ty::Tuple(_) => "tuple".to_string(),
            Ty::Con(n, args) => match n.as_str() {
                "string" => "str".to_string(),
                "bool" => "bool".to_string(),
                "List" => "list".to_string(),
                "Map" => "dict".to_string(),
                "Set" => "set".to_string(),
                // (a forward reference still brings in `Any`)
                _ if args.is_empty() => match self.user_type_ann(n) {
                    Some(a) => {
                        self.needs.any = true;
                        format!("\"{}\"", a)
                    }
                    None => "Any".to_string(),
                },
                _ => "Any".to_string(),
            },
            _ => "Any".to_string(),
        };
        if s == "Any" {
            self.needs.any = true;
        }
        s
    }

    /// `name: T` for a value bound at module level.
    pub fn annotated_target(&mut self, py: &str, t: Option<Ty>) -> String {
        if !self.native {
            return py.to_string();
        }
        match t.and_then(|t| self.native_ann(&t, true)) {
            Some(a) => format!("{}{}", py, annotation(": ", &a)),
            None => py.to_string(),
        }
    }
}

/// Stand-ins for `Some | None_` and `Ok | Error` until the module is known
/// to define (or import) those classes.
pub const OPTION_MARK: &str = "\u{4}";
pub const RESULT_MARK: &str = "\u{5}";

/// `sep` and the annotation, bracketed for later resolution when it names
/// Option or Result.
pub fn annotation(sep: &str, ann: &str) -> String {
    if ann.contains(OPTION_MARK) || ann.contains(RESULT_MARK) {
        format!("\u{2}{}{}\u{3}", sep, ann)
    } else {
        format!("{}{}", sep, ann)
    }
}

/// Settle the bracketed annotations: kept (spelled out) when the classes
/// they name are present, dropped otherwise.
pub fn resolve_annotations(text: &str, option: bool, result: bool) -> String {
    if !text.contains('\u{2}') {
        return text.to_string();
    }
    let mut out = String::new();
    let mut rest = text;
    while let Some(i) = rest.find('\u{2}') {
        out.push_str(&rest[..i]);
        let after = &rest[i + 1..];
        let j = after.find('\u{3}').unwrap_or(after.len());
        let ann = &after[..j];
        if (!ann.contains(OPTION_MARK) || option) && (!ann.contains(RESULT_MARK) || result) {
            out.push_str(&ann.replace(OPTION_MARK, "Some | None_").replace(RESULT_MARK, "Ok | Error"));
        }
        rest = if j < after.len() { &after[j + 1..] } else { "" };
    }
    out.push_str(rest);
    out
}

/// A sum type's case class written for mypyc: ordering spelled out.
pub fn adt_class_native(name: &str, annots: &[String], ordered: Option<usize>, singleton: bool) -> String {
    adt_class_native_with(name, annots, ordered, singleton, true)
}

/// `annotate_singleton`: the shared instance of a field-less case is
/// annotated with its class (only in a program with code).
pub fn adt_class_native_with(name: &str, annots: &[String], ordered: Option<usize>, singleton: bool, annotate_singleton: bool) -> String {
    let mut s = String::new();
    s.push_str("@dataclass(frozen=True, slots=True, repr=False)\n");
    s.push_str(&format!("class {}:\n", name));
    for (i, a) in annots.iter().enumerate() {
        s.push_str(&format!("    _{}: {}\n", i, a));
    }
    s.push_str("    def __repr__(self):\n");
    if annots.is_empty() {
        s.push_str(&format!("        return \"{}\"\n", name));
    } else {
        let parts: Vec<String> = (0..annots.len()).map(|i| format!("{{self._{}!r}}", i)).collect();
        s.push_str(&format!("        return f\"{}({})\"\n", name, parts.join(", ")));
    }
    if let Some(idx) = ordered {
        s.push_str("    def __eq__(self, other):\n");
        s.push_str(&format!("        return type(other) is {} and self._pf_order_key() == other._pf_order_key()\n", name));
        for (m, op) in [("__lt__", "<"), ("__le__", "<="), ("__gt__", ">"), ("__ge__", ">=")] {
            s.push_str(&format!("    def {}(self, other):\n", m));
            s.push_str(&format!("        return self._pf_order_key() {} other._pf_order_key()\n", op));
        }
        s.push_str("    def _pf_order_key(self):\n");
        if annots.is_empty() {
            s.push_str(&format!("        return ({},)\n", idx));
        } else {
            let parts: Vec<String> = (0..annots.len()).map(|i| format!("self._{}", i)).collect();
            s.push_str(&format!("        return ({}, {})\n", idx, parts.join(", ")));
        }
    }
    if singleton {
        if annotate_singleton {
            s.push_str(&format!("_{}: {} = {}()\n", name, name, name));
        } else {
            s.push_str(&format!("_{} = {}()\n", name, name));
        }
    }
    s
}

//! Phase 3 CLI: type-check, compile to Python, or echo the canonical form.
//!
//! Hand-rolled argument handling; the full clap subcommand surface (`fmt`,
//! `lsp`, …) arrives later — see `DESIGN.md` §10.
//!
//! Usage:
//!   pyfun check   <file.pyfun>                  # type-check, report diagnostics
//!   pyfun compile <file.pyfun> [-o <out>]       # type-check then lower to Python
//!   pyfun run     <file.pyfun> [--] [args...]   # compile then execute with Python
//!   pyfun parse   <file.pyfun>                  # canonical pretty-print
//!   pyfun <file.pyfun>                          # shorthand for `compile`
//!
//! `check`/`compile`/`run` operate over the **whole import graph** when the entry
//! file has `import`s (`DESIGN.md` §6.1): every module is checked/emitted, the
//! shared `_pyfun_rt.py` is produced, and `run` materializes the tree to a temp
//! directory. A file with **no imports behaves exactly as before** (single-file
//! path: `compile` to stdout/one file, `run` piped to the interpreter).

use std::path::Path;
use std::process::{Command, ExitCode, Stdio};

use pyfun::diagnostics::{self, Level};
use pyfun::project::{self, ProjectError};
use pyfun::python_emitter::PyTarget;
use pyfun::syntax::{Item, Module};

mod bundle;
mod kernel;
mod native_build;
mod packages;
mod repl;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match args.first().map(String::as_str) {
        None | Some("-h") | Some("--help") => {
            help();
            ExitCode::SUCCESS
        }
        Some("-V") | Some("--version") | Some("version") => {
            println!("pyfun {}", env!("CARGO_PKG_VERSION"));
            ExitCode::SUCCESS
        }
        Some("check") => match args.get(1) {
            Some(path) => check(path),
            None => fail("`check` needs a file path"),
        },
        Some("compile") => match parse_compile_args(&args[1..]) {
            Ok((path, out, target, native)) => compile(path, out.as_deref(), target, native),
            Err(msg) => fail(&msg),
        },
        Some("run") => match args.get(1) {
            Some(path) => {
                // Everything after the path belongs to the program (even a
                // `-o` or `--help`), so it reaches `sys.argv` exactly as it
                // would when the compiled file is run with `python` directly.
                // One leading `--` is an optional separator and is consumed.
                let prog_args = match args.get(2).map(String::as_str) {
                    Some("--") => &args[3..],
                    _ => &args[2..],
                };
                run(path, prog_args)
            }
            None => fail("`run` needs a file path"),
        },
        Some("parse") => match args.get(1) {
            Some(path) => parse_only(path),
            None => fail("`parse` needs a file path"),
        },
        Some("bundle") => match bundle::parse_args(&args[1..]) {
            Ok(parsed) => bundle::run(parsed),
            Err(msg) => fail(&msg),
        },
        Some("build") => native_build::run(&args[1..]),
        Some("add") => packages::add(&args[1..]),
        Some("install") => packages::install(),
        Some("remove") => packages::remove(&args[1..]),
        Some("lsp") => lsp_server(),
        Some("repl") => repl::run(),
        Some("kernel-engine") => kernel::run(),
        // Shorthand: a bare path means `compile <path>` to stdout.
        Some(path) => compile(path, None, PyTarget::default(), false),
    }
}

