    );
    eprintln!("  pyfun --version                           print the compiler version");
    eprintln!("  pyfun <file.pyfun>                        shorthand for `compile`");
}

/// Run the language server, speaking LSP over stdin/stdout until `exit`.
fn lsp_server() -> ExitCode {
    match pyfun::lsp::run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => fail(&format!("lsp server error: {e}")),
    }
}

fn check(path: &str) -> ExitCode {
    let Some(source) = read(path) else {
        return ExitCode::FAILURE;
    };
    let module = match pyfun::parse(&source) {
        Ok(m) => m,
        Err(e) => {
            eprintln!(
                "{}",
                diagnostics::render(&source, Level::Error, &e.message(), e.span())
            );
            return ExitCode::FAILURE;
        }
    };
    // A file with imports is the entry of a multi-module project.
    if has_imports(&module) {
        return check_project(path);
    }
    let (errors, _types, holes, _ordered, _codecs) = pyfun::types::check_collecting(&module);
    if errors.is_empty() && holes.is_empty() {
        eprintln!("ok: no type errors");
        return ExitCode::SUCCESS;
    }
    let mut first = true;
    for e in &errors {
        if !first {
            eprintln!();
        }
        first = false;
        eprintln!(
            "{}",
            diagnostics::render(&source, Level::Error, &e.message, e.span)
        );
    }
    // Typed holes are reported informatively (a "note", not an error), but they
    // keep `check` non-zero so a leftover hole is caught.
    for h in &holes {
        if !first {
            eprintln!();
        }
        first = false;
        eprintln!(
            "{}",
            diagnostics::render(&source, Level::Note, &h.message(), h.span)
        );
    }
    let n = errors.len();
    let hn = holes.len();
    if n > 0 {
        eprintln!("\n{n} error{}", if n == 1 { "" } else { "s" });
    }
    if hn > 0 {
        eprintln!("{hn} unfilled hole{}", if hn == 1 { "" } else { "s" });
    }
    ExitCode::FAILURE
}

fn compile(path: &str, out: Option<&str>, target: PyTarget, native: bool) -> ExitCode {
    let Some(source) = read(path) else {
        return ExitCode::FAILURE;
    };
    if let Ok(module) = pyfun::parse(&source)
        && has_imports(&module)
    {
        return compile_project(path, out, target, native);
    }
    let python = match pyfun::compile_with(&source, target, native) {
        Ok((py, notes)) => {
            report_notes(&notes);
            py
        }
        Err(e) => {
            eprintln!(
                "{}",
                diagnostics::render(&source, Level::Error, &e.message(), e.span())
            );
            return ExitCode::FAILURE;
        }
    };
    match out {
        Some(out_path) => match std::fs::write(out_path, python) {
            Ok(()) => {
                eprintln!("wrote {out_path}");
                ExitCode::SUCCESS
            }
            Err(e) => fail(&format!("cannot write {out_path}: {e}")),
        },
        None => {
            print!("{python}");
            ExitCode::SUCCESS
        }
    }
}

/// Compile `path` to Python (gated on type-checking), then execute it from a
/// temp file (`python <file>.py`), inheriting stdin/stdout/stderr so the program
[package]
name = "pyfun"
version = "0.10.0"
edition = "2024"
# Edition 2024's floor is Rust 1.85; the code uses nothing newer. The exact build
# toolchain is pinned separately in rust-toolchain.toml.
rust-version = "1.85"
description = "An F#-inspired, functional-first language that compiles to readable Python."
authors = ["Simon Treanor"]
license = "Apache-2.0"
repository = "https://github.com/simontreanor/Pyfun"

# The `pyfun` compiler crate stays dependency-free. The WASM playground is a separate
# workspace member that depends on `wasm-bindgen`; `default-members` keeps bare
# `cargo build` / `cargo test` scoped to the compiler, so normal workflows are
# unchanged and the playground is built explicitly with wasm-pack.
[workspace]
members = ["playground"]
default-members = ["."]

# Phase 1 is intentionally dependency-free (pure std): lexer + parser + AST + pretty-printer.
