// Lexer: bytes -> tokens with positions. Layout is decided by the parser from
// each token's column and whether it starts a line.

use crate::diag::Diag;
use crate::source::Span;

#[derive(Clone, Debug, PartialEq)]
pub enum Tok {
    Int(i64),
    Float(f64),
    Str(String),
    FStr(Vec<FPiece>),
    Ident(String),
    Upper(String),
    Hole(Option<String>),
    // keywords
    Let,
    Mut,
    Pure,
    Type,
    Measure,
    Extern,
    Import,
    Module,
    If,
    Then,
    Elif,
    Else,
    Match,
    Case,
    Fun,
    And,
    Or,
    Not,
    True,
    False,
    Return,
    With,
    As,
    Yield,
    Do,
    Try,
    // punctuation
    LParen,
    RParen,
    LBracket,
    RBracket,
    LBrace,
    RBrace,
    Comma,
    Dot,
    Ellipsis,
    Colon,
    Eq,
    Arrow,
    LArrow,
    Bar,
    Underscore,
    Bang,
    Caret,
    // operators
    Plus,
    Minus,
    Star,
    Slash,
    SlashSlash,
    Percent,
    StarStar,
    EqEq,
    NotEq,
    Lt,
    Le,
    Gt,
    Ge,
    PipeRight,
    PipeLeft,
    ComposeRight,
    ComposeLeft,
    /// (recovering) where a token failed to lex: it takes its place in the
    /// layout, and an expression simply skips it
    LexError,
    Eof,
}

#[derive(Clone, Debug, PartialEq)]
pub enum FPiece {
    Text(String),
    /// A `{...}` hole: its tokens (ending in Eof), the span of the content, and
    /// for `{expr=}` the source text echoed before the value.
    Hole { toks: Vec<Token>, span: Span, debug: Option<String> },
}

#[derive(Clone, Debug, PartialEq)]
pub struct Token {
    pub tok: Tok,
    pub span: Span,
    pub line: usize,
    pub col: usize,
    /// first token on its line
    pub bol: bool,
    /// whitespace (or a comment) right before this token
    pub space_before: bool,
}

pub fn describe(t: &Tok) -> String {
    match t {
        Tok::Int(n) => format!("integer `{}`", n),
        Tok::Float(f) => format!("float `{}`", f),
        Tok::Str(_) => "string literal".to_string(),
        Tok::Ident(s) | Tok::Upper(s) => format!("identifier `{}`", s),
        Tok::Eof => "end of input".to_string(),
        other => format!("`{}`", tok_text(other)),
    }
}

pub fn tok_text(t: &Tok) -> &'static str {
    match t {
        Tok::Let => "let",
        Tok::Mut => "mut",
        Tok::Pure => "pure",
        Tok::Type => "type",
        Tok::Measure => "measure",
        Tok::Extern => "extern",
        Tok::Import => "import",
        Tok::Module => "module",
        Tok::If => "if",
        Tok::Then => "then",
        Tok::Else => "else",
        Tok::Match => "match",
        Tok::Fun => "fun",
        Tok::And => "and",
        Tok::Or => "or",
        Tok::Not => "not",
        Tok::True => "true",
        Tok::False => "false",
        Tok::Return => "return",
        Tok::With => "with",
        Tok::Yield => "yield",
        Tok::Do => "do",
        Tok::LParen => "(",
        Tok::RParen => ")",
        Tok::LBracket => "[",
        Tok::RBracket => "]",
        Tok::LBrace => "{",
        Tok::RBrace => "}",
        Tok::Comma => ",",
        Tok::Dot => ".",
        Tok::Ellipsis => "...",
        Tok::Colon => ":",
        Tok::Eq => "=",
        Tok::Arrow => "->",
        Tok::LArrow => "<-",
        Tok::Bar => "|",
        Tok::Underscore => "_",
        Tok::Bang => "!",
        Tok::Caret => "^",
        Tok::Plus => "+",
        Tok::Minus => "-",
        Tok::Star => "*",
        Tok::Slash => "/",
        Tok::SlashSlash => "//",
        Tok::EqEq => "==",
        Tok::NotEq => "!=",
        Tok::Lt => "<",
        Tok::Le => "<=",
        Tok::Gt => ">",
        Tok::Ge => ">=",
        Tok::PipeRight => "|>",
        Tok::PipeLeft => "<|",
        Tok::ComposeRight => ">>",
        Tok::ComposeLeft => "<<",
        // the original's token display falls back to this for newer tokens
        _ => "token",
    }
}

fn keyword(s: &str) -> Option<Tok> {
    Some(match s {
        "let" => Tok::Let,
        "mut" => Tok::Mut,
        "pure" => Tok::Pure,
        "type" => Tok::Type,
        "measure" => Tok::Measure,
        "extern" => Tok::Extern,
        "import" => Tok::Import,
        "module" => Tok::Module,
        "if" => Tok::If,
        "then" => Tok::Then,
        "elif" => Tok::Elif,
        "else" => Tok::Else,
        "match" => Tok::Match,
        "case" => Tok::Case,
        "fun" => Tok::Fun,
        "and" => Tok::And,
        "or" => Tok::Or,
        "not" => Tok::Not,
        "true" => Tok::True,
        "false" => Tok::False,
        "return" => Tok::Return,
        "with" => Tok::With,
        "as" => Tok::As,
        "yield" => Tok::Yield,
        "do" => Tok::Do,
        "try" => Tok::Try,
        _ => return None,
    })
}

