                for e in &echoes {
                    println!("{}", e);
                }
                for e in errs {
                    eprintln!("{}", e);
                }
            }
        }
    }
}

enum Line {
    Text(String),
    Eof,
    Invalid,
}

fn read_line(stdin: &mut std::io::StdinLock) -> Line {
    let mut buf = Vec::new();
    match stdin.read_until(b'\n', &mut buf) {
        Ok(0) => Line::Eof,
        Ok(_) => match String::from_utf8(buf) {
            Ok(s) => Line::Text(s.trim_end_matches('\n').trim_end_matches('\r').to_string()),
            Err(_) => Line::Invalid,
        },
        Err(_) => Line::Invalid,
    }
}

